    person(W, group, [4.5, 0, 17], { robe: 0x060402, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, staff: 'planted', bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: -0.62, s: 1.19 });
